// src/lib/mcp/generate-content.ts
var goalMap = { educate: "Educar a la audiencia", inspire: "Inspirar y motivar", promote: "Promocionar un producto o servicio", engage: "Generar engagement y conversaci\xF3n", storytelling: "Contar una historia" };
var toneMap = { professional: "profesional", casual: "casual y cercano", inspirational: "inspiracional", direct: "directo y conciso", humorous: "con humor" };
var lengthMap = { short: "corto (~100 palabras)", medium: "medio (~200 palabras)", long: "largo (~300 palabras)" };
var ctaMap = { question: "una pregunta abierta al lector", share: "invitar a compartir", follow: "invitar a seguir", link: "invitar a visitar un enlace", none: "sin call to action" };
var langMap = { es: "espa\xF1ol", en: "ingl\xE9s", pt: "portugu\xE9s" };
async function generateContent(supabase, params) {
  let sourceTexts = [];
  if (params.input_ids?.length) {
    const { data: inputs } = await supabase.from("inputs").select("title, raw_content, extracted_content, summary, original_url, type").in("id", params.input_ids);
    sourceTexts = (inputs || []).map((inp) => {
      const content = inp.extracted_content || inp.raw_content || inp.summary || "";
      return `[${inp.type.toUpperCase()}] ${inp.title}
${content}${inp.original_url ? `
URL: ${inp.original_url}` : ""}`;
    });
  }
  let voiceTexts = [];
  if (params.voice_id) {
    const { data: samples } = await supabase.from("voice_samples").select("title, content").eq("voice_id", params.voice_id).limit(10);
    if (samples?.length) voiceTexts = samples.map((s) => `${s.title ? `[${s.title}] ` : ""}${s.content}`);
  }
  let systemPrompt = `Eres un experto creador de contenido para LinkedIn.
Generas posts de alta calidad, optimizados para engagement.
Usa emojis con moderaci\xF3n, formato con saltos de l\xEDnea y estructura visual clara.
NO uses markdown (ni asteriscos ni negritas), escribe en texto plano.
IMPORTANTE: NO empieces el post con texto entre corchetes.`;
  if (voiceTexts.length > 0) {
    systemPrompt += `

ESTILO DE ESCRITURA - Imita este estilo:
${voiceTexts.map((t, i) => `--- Ejemplo ${i + 1} ---
${t}`).join("\n\n")}
--- Fin ---`;
  }
  let userPrompt = "Genera un post para LinkedIn";
  if (sourceTexts.length > 0) userPrompt += ` bas\xE1ndote en:

${sourceTexts.join("\n\n---\n\n")}`;
  const specs = [];
  if (params.goal && goalMap[params.goal]) specs.push(`Objetivo: ${goalMap[params.goal]}`);
  if (params.tone && toneMap[params.tone]) specs.push(`Tono: ${toneMap[params.tone]}`);
  if (params.language && langMap[params.language]) specs.push(`Idioma: ${langMap[params.language]}`);
  if (params.length && lengthMap[params.length]) specs.push(`Longitud: ${lengthMap[params.length]}`);
  if (params.cta && ctaMap[params.cta]) specs.push(`CTA: ${ctaMap[params.cta]}`);
  if (params.target_audience) specs.push(`Audiencia objetivo: ${params.target_audience}`);
  if (specs.length) userPrompt += `

Especificaciones:
${specs.join("\n")}`;
  if (params.content_focus) userPrompt += `

ENFOQUE:
${params.content_focus}`;
  userPrompt += "\n\nDevuelve solo el post, sin explicaciones ni metadatos.";
  const LOVABLE_API_KEY = process.env.LOVABLE_API_KEY;
  if (!LOVABLE_API_KEY) throw new Error("LOVABLE_API_KEY is not configured");
  const aiResponse = await fetch("https://ai.gateway.lovable.dev/v1/chat/completions", {
    method: "POST",
    headers: { Authorization: `Bearer ${LOVABLE_API_KEY}`, "Content-Type": "application/json" },
    body: JSON.stringify({
      model: "google/gemini-3-flash-preview",
      messages: [
        { role: "system", content: systemPrompt },
        { role: "user", content: userPrompt }
      ]
    })
  });
  if (!aiResponse.ok) {
    const e = await aiResponse.text();
    throw new Error(`AI error ${aiResponse.status}: ${e}`);
  }
  const aiResult = await aiResponse.json();
  return (aiResult.choices?.[0]?.message?.content || "").replace(/^\s*\[.*?\]\s*/g, "");
}

