// src/lib/mcp/tools/import-newsletter-item.ts
import { defineTool as defineTool17 } from "npm:@lovable.dev/mcp-js@0.22.2";
import { z as z15 } from "npm:zod@^4.4.3";
var import_newsletter_item_default = defineTool17({
  name: "import_newsletter_item_as_input",
  title: "Import newsletter item",
  description: "Import a newsletter item into the library as a reusable input.",
  inputSchema: {
    item_id: z15.string(),
    extract_content: z15.boolean().optional()
  },
  annotations: { readOnlyHint: false, openWorldHint: true },
  handler: async ({ item_id, extract_content }, ctx) => {
    requireAuth(ctx);
    const supabase = supabaseForUser(ctx);
    const { data: item, error: ie } = await supabase.from("newsletter_items").select("*").eq("id", item_id).single();
    if (ie) throw ie;
    if (item.input_id) {
      const { data: existing } = await supabase.from("inputs").select("*").eq("id", item.input_id).single();
      return jsonResult({ input: existing, already_imported: true });
    }
    const isYoutube = (item.url || "").includes("youtube.com") || (item.url || "").includes("youtu.be");
    const type = isYoutube ? "youtube" : "url";
    let extracted = null;
    if (extract_content) {
      const SUPABASE_URL = process.env.SUPABASE_URL;
      const ANON_KEY = process.env.SUPABASE_PUBLISHABLE_KEY ?? process.env.SUPABASE_ANON_KEY;
      try {
        const ex = await fetch(`${SUPABASE_URL}/functions/v1/extract-url`, {
          method: "POST",
          headers: { Authorization: `Bearer ${ctx.getToken()}`, "Content-Type": "application/json", apikey: ANON_KEY },
          body: JSON.stringify({ url: item.url })
        });
        if (ex.ok) {
          const d = await ex.json();
          extracted = d.content || d.extracted_content || null;
        }
      } catch {
      }
    }
    const { data: input, error: ce } = await supabase.from("inputs").insert({
      user_id: ctx.getUserId(),
      title: item.title,
      type,
      original_url: item.url,
      raw_content: extracted,
      summary: item.description || null
    }).select().single();
    if (ce) throw ce;
    await supabase.from("newsletter_items").update({ imported_to_library: true, input_id: input.id }).eq("id", item_id);
    return jsonResult({ input, already_imported: false });
  }
});

// src/lib/mcp/tools/generate-posts-from-newsletter.ts
import { defineTool as defineTool18 } from "npm:@lovable.dev/mcp-js@0.22.2";
import { z as z16 } from "npm:zod@^4.4.3";
var generate_posts_from_newsletter_default = defineTool18({
  name: "generate_posts_from_newsletter",
  title: "Generate posts from newsletter",
  description: "Atomic daily-agent action: import all items from a newsletter, generate 1 draft post per item, and return the created posts. Idempotent per (user, newsletter_item).",
  inputSchema: {
    newsletter_id: z16.string(),
    voice_id: z16.string().optional(),
    goal: z16.string().optional(),
    tone: z16.string().optional(),
    language: z16.string().optional(),
    length: z16.string().optional(),
    cta: z16.string().optional(),
    target_audience: z16.string().optional(),
    content_focus: z16.string().optional(),
    extract_content: z16.boolean().optional()
  },
  annotations: { readOnlyHint: false, openWorldHint: true },
  handler: async (params, ctx) => {
    requireAuth(ctx);
    const supabase = supabaseForUser(ctx);
    const userId = ctx.getUserId();
    const SUPABASE_URL = process.env.SUPABASE_URL;
    const ANON_KEY = process.env.SUPABASE_PUBLISHABLE_KEY ?? process.env.SUPABASE_ANON_KEY;
    const { data: items, error } = await supabase.from("newsletter_items").select("*").eq("newsletter_id", params.newsletter_id);
    if (error) throw error;
    if (!items?.length) return jsonResult({ posts: [], skipped: 0, message: "No items in newsletter" });
    const results = [];
    let skipped = 0;
    for (const item of items) {
      const { data: existing } = await supabase.from("generated_posts").select("id").eq("user_id", userId).eq("source_newsletter_item_id", item.id).maybeSingle();
      if (existing) {
        skipped++;
        continue;
      }
      let inputId = item.input_id;
      if (!inputId) {
        const isYoutube = (item.url || "").includes("youtube.com") || (item.url || "").includes("youtu.be");
        let extracted = null;
        if (params.extract_content) {
          try {
            const ex = await fetch(`${SUPABASE_URL}/functions/v1/extract-url`, {
              method: "POST",
              headers: { Authorization: `Bearer ${ctx.getToken()}`, "Content-Type": "application/json", apikey: ANON_KEY },
              body: JSON.stringify({ url: item.url })
            });
            if (ex.ok) {
              const d = await ex.json();
              extracted = d.content || d.extracted_content || null;
            }
          } catch {
          }
        }
        const { data: newInput, error: ie } = await supabase.from("inputs").insert({
          user_id: userId,
          title: item.title,
          type: isYoutube ? "youtube" : "url",
          original_url: item.url,
          raw_content: extracted,
          summary: item.description || null
        }).select().single();
        if (ie) {
          results.push({ item_id: item.id, error: ie.message });
          continue;
        }
        inputId = newInput.id;
        await supabase.from("newsletter_items").update({ imported_to_library: true, input_id: inputId }).eq("id", item.id);
      }
      try {
        const content = await generateContent(supabase, { ...params, input_ids: [inputId] });
        const { data: post, error: pe } = await supabase.from("generated_posts").insert({
          user_id: userId,
          content,
          title: item.title,
          input_id: inputId,
          input_ids: [inputId],
          goal: params.goal ?? null,
          tone: params.tone ?? null,
          language: params.language ?? null,
          length: params.length ?? null,
          cta: params.cta ?? null,
          target_audience: params.target_audience ?? null,
          content_focus: params.content_focus ?? null,
          voice_id: params.voice_id ?? null,
          status: "draft",
          source_newsletter_id: params.newsletter_id,
          source_newsletter_item_id: item.id
        }).select("id, title").single();
        if (pe) {
          results.push({ item_id: item.id, error: pe.message });
          continue;
        }
        results.push({ item_id: item.id, input_id: inputId, post_id: post.id, title: post.title });
      } catch (e) {
        results.push({ item_id: item.id, error: e.message });
      }
    }
    return jsonResult({ posts: results, skipped, total_items: items.length });
  }
});

